const stdout = $input.first()?.json?.stdout;
if (typeof stdout !== 'string' || !stdout.trim()) {
  throw new Error('The local verification script returned no JSON report.');
}
const report = JSON.parse(stdout.trim());
const lines = [
  `MADAR V2 system check — ${report.overall}`,
  `Checked: ${report.checkedAt}`,
  ...report.checks.map((check) => `${check.status}: ${check.name} — ${JSON.stringify(check.details)}`),
];
if (report.overall === 'FAIL') {
  throw new Error(lines.join('\n'));
}
return [{ json: { ...report, supervisorReport: lines.join('\n'), delivery: 'Available in this n8n execution only; no external notification channel is configured.' } }];
